# Complete-chain dataset for the calibration replay: fixed 15-draft cycles,
# every row labelled (--draft-trace), sampled at Gemma defaults plus greedy.
import json, subprocess, sys, time, urllib.request
from pathlib import Path
ROOT = Path('/home/franz/projects/gufo')
sys.path.insert(0, str(ROOT / 'tools/gemma4'))
import draft_policy_bench as dpb
OUT = Path('/tmp/g4-drafter-study')
BIN = '/tmp/gufo-study-c812aea8'
M = '/home/franz/models/gemma-4/'
T31 = 'gemma-31b-it/gemma-4-31B-it-UD-Q4_K_XL.gguf'
MODELS = {'q8': (T31, 'drafts/31b-assistant/gemma-4-31B-it-assistant.Q8_0.gguf'),
          'bf16': (T31, 'drafts/31b-unsloth-mtp/MTP/mtp-gemma-4-31B-it-BF16.gguf'),
          'q8u': (T31, 'drafts/31b-unsloth-mtp/MTP/mtp-gemma-4-31B-it-Q8_0.gguf')}
DEFAULTS = {'temperature': 1.0, 'top_k': 64, 'top_p': 0.95, 'repeat_penalty': 1.0}
DOC = Path('/tmp/opencode/mtp-exp/document.txt').read_text()
ESSAY = DOC + '\n\nWrite a short essay (about 400 words) on the engineering trade-offs the document above describes.'
PORT = 8099

def requests():
    w = {name: (n, reqs) for name, n, reqs in dpb.workloads()}
    out = []
    for i, r in enumerate(w['prose'][1]):
        out.append(('prose', 'sampled', 256, r['prompt'], dict(DEFAULTS, seed=100 + i)))
    for s in range(1, 13):
        out.append(('story', 'sampled', 128, w['story'][1][0]['prompt'], dict(DEFAULTS, seed=s)))
    for s in range(1, 7):
        out.append(('code-write', 'sampled', 384, w['code-write'][1][0]['prompt'], dict(DEFAULTS, seed=s)))
    for s in range(1, 4):
        out.append(('code-edit', 'sampled', 384, w['code-edit'][1][0]['prompt'], dict(DEFAULTS, seed=s)))
    for s in range(1, 4):
        out.append(('essay-31k', 'sampled', 400, ESSAY, dict(DEFAULTS, seed=s)))
    for i, r in enumerate(w['prose'][1][:6]):
        out.append(('prose', 'greedy', 256, r['prompt'], {'temperature': 0}))
    for name in ['code-write', 'code-edit', 'repetitive']:
        out.append((name, 'greedy', w[name][0], w[name][1][0]['prompt'], {'temperature': 0}))
    out.append(('essay-31k', 'greedy', 400, ESSAY, {'temperature': 0}))
    return out

def post(body):
    req = urllib.request.Request(f'http://127.0.0.1:{PORT}/v1/chat/completions', data=json.dumps(body).encode(),
                                 headers={'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=1800) as r:
        return json.loads(r.read())

for model in sys.argv[1].split(','):
    target, draft = MODELS[model]
    trace = OUT / f'trace-{model}.jsonl'
    trace.unlink(missing_ok=True)
    cmd = [BIN, 'serve', 'llm', '--port', str(PORT), '--model', M + target, '--speculative', 'mtp', '--mtp-model', M + draft,
           '--context', '40960', '--sessions', '1', '--think', 'off', '--served-model-name', 'bench',
           '--draft-policy', 'fixed', '--draft-tokens', '15', '--draft-trace', str(trace)]
    meta = {'model': model, 'command': cmd, 'requests': []}
    with (OUT / f'server-{model}.log').open('w') as log:
        srv = subprocess.Popen(cmd, stdout=log, stderr=subprocess.STDOUT)
        try:
            for _ in range(900):
                if srv.poll() is not None: raise RuntimeError('server exited')
                try: urllib.request.urlopen(f'http://127.0.0.1:{PORT}/ready', timeout=2); break
                except Exception: time.sleep(1)
            post({'model': 'bench', 'max_tokens': 8, 'messages': [{'role': 'user', 'content': 'Hi'}]})
            for name, mode, n, prompt, sampling in requests():
                t0 = time.monotonic_ns()
                r = post({'model': 'bench', 'max_tokens': n, **sampling, 'messages': [{'role': 'user', 'content': prompt}]})
                meta['requests'].append({'workload': name, 'mode': mode, 'sampling': sampling, 'start_ns': t0,
                                         'end_ns': time.monotonic_ns(), 'timings': r['timings']})
                print(model, name, mode, sampling.get('seed'), r['timings']['predicted_n'], flush=True)
                (OUT / f'meta-{model}.json').write_text(json.dumps(meta, indent=1))
        finally:
            srv.terminate()
            try: srv.wait(timeout=60)
            except subprocess.TimeoutExpired: srv.kill(); srv.wait()

