"""Per-drafter acceptance from fixed 15-draft traces (collect.py output).

Cycles with prompt-lookup copies are dropped (they mix copied and drafted
rows). Per cycle, E[accepted] = sum_i prod_{j<=i} a_j over its drafted rows;
a_i is the row's acceptance given the rows before it accepted (greedy 0/1,
sampled min(1, p/q)). Intervals: 2000 bootstrap resamples over requests.
"""
import json, random, sys
from pathlib import Path
from collections import defaultdict

D = Path(sys.argv[1])
arms = sys.argv[2].split(',')
random.seed(20261021)


def load(arm):
    meta = json.loads((D / f'meta-{arm}.json').read_text())
    reqs = meta['requests']
    cycles = defaultdict(list)  # request index -> list of row_acceptance
    for line in (D / f'trace-{arm}.jsonl').open():
        r = json.loads(line)
        if r.get('copied', 0) != 0 or not r['row_acceptance']:
            continue
        t = r['begin_ns']
        for i, q in enumerate(reqs):
            if q['start_ns'] <= t <= q['end_ns']:
                cycles[i].append(r['row_acceptance'])
                break
    return reqs, cycles


def expected(rows):
    total, prod = 0.0, 1.0
    for a in rows:
        prod *= a
        total += prod
    return total


def summarize(reqs, cycles, select):
    ids = [i for i, q in enumerate(reqs) if select(q) and cycles.get(i)]
    per = {i: [expected(c) for c in cycles[i]] for i in ids}
    pos = {i: cycles[i] for i in ids}

    def stat(sample):
        vals = [v for i in sample for v in per[i]]
        return sum(vals) / len(vals) if vals else float('nan')

    def pos_stat(sample, k):
        vals = [c[k] for i in sample for c in pos[i] if len(c) > k]
        return sum(vals) / len(vals) if vals else float('nan')

    point = stat(ids)
    boots = sorted(stat([random.choice(ids) for _ in ids]) for _ in range(2000))
    return {'requests': len(ids), 'cycles': sum(len(per[i]) for i in ids),
            'expected_accepted': point, 'ci95': (boots[50], boots[1949]),
            'position_acceptance': [pos_stat(ids, k) for k in range(8)]}


groups = {
    'greedy (all)': lambda q: q['mode'] == 'greedy',
    'sampled (all)': lambda q: q['mode'] == 'sampled',
}
for w in ['prose', 'story', 'code-write', 'code-edit', 'essay-31k', 'repetitive']:
    for mode in ['greedy', 'sampled']:
        groups[f'{w} {mode}'] = (lambda w, mode: lambda q: q['workload'] == w and q['mode'] == mode)(w, mode)

out = {}
for arm in arms:
    if not (D / f'meta-{arm}.json').exists():
        continue
    reqs, cycles = load(arm)
    out[arm] = {g: summarize(reqs, cycles, f) for g, f in groups.items()}
print(f"{'group':22s} " + ' '.join(f'{a:>26s}' for a in out))
for g in groups:
    cells = []
    for a in out:
        s = out[a][g]
        if s['requests'] == 0:
            cells.append(f"{'-':>26s}")
            continue
        cells.append(f"{s['expected_accepted']:6.3f} [{s['ci95'][0]:5.3f},{s['ci95'][1]:5.3f}] n={s['cycles']:4d}")
    if any(c.strip() != '-' for c in cells):
        print(f'{g:22s} ' + ' '.join(cells))
print('\nposition acceptance (1..8), all greedy / all sampled:')
for a in out:
    for g in ['greedy (all)', 'sampled (all)']:
        print(f"{a:5s} {g:14s} " + ' '.join(f'{v:.3f}' for v in out[a][g]['position_acceptance']))
json.dump(out, open(D / 'summary.json', 'w'), indent=1)
